import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, fromEvent, merge, interval, of, firstValueFrom } from 'rxjs';
import { catchError, map, switchMap, startWith } from 'rxjs/operators';
import { environment } from '../../../../environments/environment';


@Injectable({
  providedIn: 'root'
})
export class NetworkStatusService {
  private onlineSubject = new BehaviorSubject<boolean>(true);

  constructor(private http: HttpClient) {
    this.init();
  }

  private checkInternetConnection() {
    // Use a reliable endpoint that supports CORS
    const connectivityCheckUrl = `${environment.connectivityCheckUrl}`;
    return this.http.get(connectivityCheckUrl, { responseType: 'text' }).pipe(
      map(() => true),
      catchError(error => {
        console.warn('Connectivity check failed:', error);
        return of(false);
      })
    );
  }

  async checkNetworkStatus(): Promise<boolean> {
    const connectivityCheckUrl = `${environment.connectivityCheckUrl}`;

    try {
      const result = await firstValueFrom(
        this.http.get(connectivityCheckUrl, { responseType: 'text' }).pipe(
          map(() => true),
          catchError(error => {
            console.warn('Connectivity check failed:', error);
            return of(false);
          })
        )
      );
      return result;
    } catch (error) {
      console.error('Unexpected error during network check:', error);
      return false;
    }
  }

  private init() {
    const online$ = fromEvent(window, 'online').pipe(map(() => true));
    const offline$ = fromEvent(window, 'offline').pipe(map(() => false));

    // Combine online/offline events with actual internet check every 10s
    merge(online$, offline$, interval(10000).pipe(map(() => navigator.onLine)))
      .pipe(
        startWith(navigator.onLine),
        switchMap(() => this.checkInternetConnection())
      )
      .subscribe(status => this.onlineSubject.next(status));
  }

  get isOnline$() {
    return this.onlineSubject.asObservable();
  }
}